    int n = Integer.parseInt(sc.next());
    int[] a = new int[n];
    for (int i = 0; i < n; i++) {
        a[i] = Integer.parseInt(sc.next());
    }

    for (int i = 0; i < n; i++) {
        int amount = a[i];
        int[] denominations = {500, 100, 50, 10, 5, 1};

        for (int denom : denominations) {
            int numCoins = Math.min(amount / denom, coins.get(denom));
            amount -= numCoins * denom;
            coins.put(denom, coins.get(denom) - numCoins);
        }

        if (amount > 0) {
            System.out.println("No");
            return;
        }
    }

    System.out.println("Yes");
